// Efecto de los golpes que NO pegan, por lo que HACEN. Un
// Tail Whip es de tipo normal, y con el efecto del tipo se
// veia el tajo de Vice Grip: bajar la defensa parecia un
// aranazo. El orden es el de FXS_* en battle_ui.ino.
#define FX_SUP_COUNT 5
static const FxAnim FX_SUP[5] = {
  { ART_FS0, 4, 3 },   // RAISE
  { ART_FS1, 6, 2 },   // LOWER
  { ART_FS2, 5, 3 },   // HEAL
  { ART_FS3, 5, 3 },   // GUARD
  { ART_FS4, 6, 3 },   // OTHER
};

// El efecto PROPIO de cada golpe vive en la TARJETA
// (/fx/fx.bin, lo escribe este mismo generador): son el 90%
// de los datos de arte y solo hace falta el del golpe que se
// acaba de lanzar. En flash queda solo quien TIENE uno.
// Los de TIPO y los de apoyo si se quedan aqui: son 23 y
// hacen que el combate nunca se quede sin efecto sin SD.
#define FX_MOVE_COUNT 731
static const uint8_t FX_HAS_OWN[] = {
  254, 251, 173, 237, 239, 254, 181, 251, 251, 191, 251, 167, 191, 212, 255, 255,
  247, 255, 223, 255, 255, 255, 231, 149, 255, 191, 255, 127, 222, 255, 127, 87,
  237, 255, 255, 247, 255, 255, 255, 255, 235, 239, 254, 255, 251, 15, 189, 215,
  253, 157, 253, 219, 127, 254, 255, 255, 223, 255, 249, 255, 79, 255, 253, 255,
  191, 235, 125, 247, 255, 251, 255, 253, 247, 255, 251, 253, 239, 255, 186, 255,
  220, 159, 255, 30, 239, 238, 255, 255, 191, 239, 255, 5,
};
static inline bool fxHasOwn(uint16_t mv) {
  return mv < FX_MOVE_COUNT && (FX_HAS_OWN[mv >> 3] & (1 << (mv & 7)));
}

