// Simbolo de cada tipo, en el MISMO orden que la hoja del
// Anil. La traduccion de ese orden a nuestros T_* vive en
// TYPE_ART de dex.h; aqui solo esta el dibujo.
#define ART_TYPE_ROWS 19
static const Art *const ART_TYPE_SHEET[19] = {
  &ART_TY0, &ART_TY1, &ART_TY2, &ART_TY3, &ART_TY4,
  &ART_TY5, &ART_TY6, &ART_TY7, &ART_TY8, nullptr,
  &ART_TY10, &ART_TY11, &ART_TY12, &ART_TY13, &ART_TY14,
  &ART_TY15, &ART_TY16, &ART_TY17, &ART_TY18,
};
// El color del cuadro que llevaba cada simbolo detras. El
// dibujo es blanco y esta pensado para leerse encima de ESTE
// color, asi que la chapa se pinta con el.
static const uint16_t ART_TYPE_BG[19] = {
  0x8430, 0xE484, 0x757A, 0x92B9, 0xAB87, 0xAD0F, 0xA505, 0x724E,
  0x6D79, 0x5B7C, 0xE307, 0x34FB, 0x4CA6, 0xDDC5, 0xEB72, 0x4E79,
  0x5B98, 0x4A49, 0xE47C,
};

// Fila de la hoja que le toca a cada T_* nuestro.
static inline const Art *typeArt(uint8_t t) {
  static const int8_t FILA[] = { -1, 0, 1, 2, 3, 4, 5, 6, 7, 10, 11, 12, 13, 14, 15, 16, 17, 8, 18 };
  if (t >= sizeof(FILA) / sizeof(FILA[0])) return nullptr;
  int8_t f = FILA[t];
  return (f < 0 || f >= ART_TYPE_ROWS) ? nullptr : ART_TYPE_SHEET[f];
}

// El color de chapa que acompana a ese simbolo. 0 = no hay.
static inline uint16_t typeArtBg(uint8_t t) {
  static const int8_t FILA[] = { -1, 0, 1, 2, 3, 4, 5, 6, 7, 10, 11, 12, 13, 14, 15, 16, 17, 8, 18 };
  if (t >= sizeof(FILA) / sizeof(FILA[0])) return 0;
  int8_t f = FILA[t];
  return (f < 0 || f >= ART_TYPE_ROWS) ? 0 : ART_TYPE_BG[f];
}

